-- Apply the new brief to three previous administrator edits only when their exact editorial copy is unchanged.
UPDATE products SET editorial_json='{"story":"Ilustrația tematică aduce farmecul unei seri cu dovleci și povești spuse pe întuneric. Mecanismul la vedere face din cutiuță un mic detaliu de decor care merită descoperit de aproape.","melody":"Modelul este asociat cu „This Is Halloween”. Melodia accentuează atmosfera jucăușă și misterioasă a sezonului, fără să încarce decorul.","use":"Așaz-o lângă decorul de toamnă și pornește melodia când primești oaspeți sau pregătești o seară tematică. Se acționează manual, exact când vrei tu.","gift":"Pentru gazda unei petreceri de Halloween, un colecționar de obiecte tematice sau un prieten care așteaptă toamna tot anul.","closing":"Misterul începe cu o rotire."}',name='Cutiuță muzicală Halloween',tagline='Un strop de mister pentru serile de octombrie.',short_description='Cutiuță din lemn cu ilustrație de Halloween și manivelă.',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='halloween' AND editorial_json IS NULL AND name='Cutiuță Muzicală Halloween cu Manivelă – Cadou Misterios & Decor Tematic' AND tagline='O mică poveste misterioasă, numai bună pentru sezonul dovlecilor.' AND short_description='Cutiuță muzicală din lemn cu ilustrație de Halloween și mecanism manual cu manivelă.' AND description='Un detaliu care schimbă atmosfera unui colț de raft: ilustrația de Halloween, lemnul și mecanismul muzical la vedere dau acestei cutiuțe un farmec misterios. Deschizi capacul și rotești manivela ca să pornești melodia, fără baterii. Se potrivește unui decor de sezon sau unui cadou pentru cineva care așteaptă cu drag serile de octombrie.' AND story='O idee de dar pentru colecționari și gazde care preferă decorurile cu poveste, nu doar ornamentele obișnuite.';
UPDATE products SET dimensions_text='aprox. 6,4 × 3,8 × 5 cm' WHERE slug='halloween' AND editorial_json IS NOT NULL AND (dimensions_text IS NULL OR trim(dimensions_text)='');
UPDATE products SET description=json_extract(editorial_json,'$.story') || ' ' || json_extract(editorial_json,'$.melody'),story=json_extract(editorial_json,'$.gift'),seo_title=name || ' | Cutiuța Magică',seo_description=short_description || ' ' || tagline,version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='halloween' AND editorial_json IS NOT NULL AND description='Un detaliu care schimbă atmosfera unui colț de raft: ilustrația de Halloween, lemnul și mecanismul muzical la vedere dau acestei cutiuțe un farmec misterios. Deschizi capacul și rotești manivela ca să pornești melodia, fără baterii. Se potrivește unui decor de sezon sau unui cadou pentru cineva care așteaptă cu drag serile de octombrie.' AND story='O idee de dar pentru colecționari și gazde care preferă decorurile cu poveste, nu doar ornamentele obișnuite.';
UPDATE products SET editorial_json='{"story":"Capacul se deschide spre un mic univers de magie, iar mecanismul rămâne la vedere. O așezi printre cărțile preferate și fiecare rotire a manivelei readuce povestea mai aproape.","melody":"Modelul este asociat cu „Hedwig''s Theme”, tema pe care fanii o recunosc din primele note. Melodia dă unui obiect mic atmosfera unei întoarceri la Hogwarts.","use":"Deschide cutiuța la o pauză de lectură sau când vrei să-i arăți unui prieten un detaliu din colecția ta. Rotește manivela lent, în ritmul în care vrei să asculți.","gift":"Pentru un fan Harry Potter, la aniversare, Crăciun ori Secret Santa; o poți oferi alături de o carte sau de un mesaj personal.","closing":"O mică întoarcere la magie."}',name='Cutiuță muzicală Harry Potter „I''m a Keeper”',tagline='Pentru cineva care ține mereu puțină magie aproape.',short_description='Cutiuță din lemn închis, cu temă Harry Potter și manivelă.',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='hp-keeper' AND editorial_json IS NULL AND name='Cutiuță Muzicală Harry Potter cu Manivelă – Cadou de Colecție' AND tagline='Un strop de magie pentru raftul cu povești preferate.' AND short_description='Cutiuță muzicală din lemn închis, cu detalii tematice, manivelă și mecanism vizibil.' AND description='Pentru fanul care păstrează poveștile cu magie aproape: o cutiuță din lemn închis, cu detalii tematice și mecanism la vedere. Deschizi capacul și rotești manivela pentru a asculta melodia, fără baterii. Un dar compact care își găsește locul pe birou, în bibliotecă sau într-o colecție dragă.' AND story='O alegere personală pentru aniversări, Secret Santa sau pentru cineva care zâmbește imediat când recunoaște universul preferat.';
UPDATE products SET dimensions_text='aprox. 6,5 × 5 × 4 cm; cu capacul deschis, înălțime aprox. 6,2 cm' WHERE slug='hp-keeper' AND editorial_json IS NOT NULL AND (dimensions_text IS NULL OR trim(dimensions_text)='');
UPDATE products SET description=json_extract(editorial_json,'$.story') || ' ' || json_extract(editorial_json,'$.melody'),story=json_extract(editorial_json,'$.gift'),seo_title=name || ' | Cutiuța Magică',seo_description=short_description || ' ' || tagline,version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='hp-keeper' AND editorial_json IS NOT NULL AND description='Pentru fanul care păstrează poveștile cu magie aproape: o cutiuță din lemn închis, cu detalii tematice și mecanism la vedere. Deschizi capacul și rotești manivela pentru a asculta melodia, fără baterii. Un dar compact care își găsește locul pe birou, în bibliotecă sau într-o colecție dragă.' AND story='O alegere personală pentru aniversări, Secret Santa sau pentru cineva care zâmbește imediat când recunoaște universul preferat.';
UPDATE products SET editorial_json='{"story":"Sub luna desenată, pisicuța transformă cutiuța într-un mic obiect de păstrat aproape. Lemnul deschis și detaliile gravate îi dau un aer cald, potrivit unui colț personal.","melody":"Modelul este asociat cu „La Vie en Rose”. Melodia completează firesc imaginea delicată, ca un mesaj tandru spus fără multe cuvinte.","use":"O poți lăsa pe noptieră sau pe birou și o poți porni într-o clipă liniștită, prin rotirea manivelei. Este un mod simplu de a-i spune cuiva „m-am gândit la tine”.","gift":"Pentru un iubitor de pisici, de ziua lui, la o aniversare în doi sau ca surpriză fără ocazie specială.","closing":"Un gest mic, cu multă tandrețe."}',name='Cutiuță muzicală Pisicuță și Lună',tagline='O surpriză blândă pentru omul care iubește pisicile.',short_description='Cutiuță din lemn deschis, cu pisicuță, lună și manivelă.',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='kitten' AND editorial_json IS NULL AND name='Cutiuță Muzicală cu Pisicuță și Lună – Manivelă, Cadou de Colecție' AND tagline='Un gest mic și tandru pentru cineva care iubește pisicile.' AND short_description='Cutiuță muzicală din lemn deschis, cu pisicuță, lună și mecanism manual cu manivelă.' AND description='Pentru iubitorii de pisici și de daruri cu poveste, această cutiuță aduce împreună ilustrația cu pisicuță și lună, lemnul deschis și o melodie caldă. Ridici capacul, apoi rotești manivela pentru a asculta mecanismul muzical, fără baterii. O surpriză delicată pentru o aniversare sau un simplu „m-am gândit la tine”.' AND story='Mică și ușor de așezat pe birou ori pe raft, păstrează farmecul unui gest personal mult după momentul în care a fost oferită.';
UPDATE products SET dimensions_text='aprox. 6,4 × 3,6 × 5 cm' WHERE slug='kitten' AND editorial_json IS NOT NULL AND (dimensions_text IS NULL OR trim(dimensions_text)='');
